-- Oracle SaaS CIS: adds one finished assessment run to the prod Digital CISO database.
-- Source: local standalone run #14 (finished 2026-11-22 17:52 UTC), with the Fusion results
--   (4.1.3, 4.3, 5.1.2, 5.3.7 and the ghost-employee list) carried forward from run #13 (29 Oct 2026).
-- Tenant: ca7a6e59-866c-40f0-8df1-8ee54f326b9a
-- Rows: 1 run, 44 results, 2049 identities (dormant 1755, active 141, ghost 153, payment 0).
-- Counts: 2 PASS, 10 FAIL, 32 MANUAL.
-- Only INSERTs; existing runs are not changed. Safe to review first: it runs in one transaction and stops on any error.
-- Run:  psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f prod_import_oracle_cis_run.sql

BEGIN;
DO $import$
DECLARE rid bigint;
BEGIN
  -- the Oracle CIS tables use row-level security: act as the prod tenant for this transaction only
  PERFORM set_config('api.tenant_id', 'ca7a6e59-866c-40f0-8df1-8ee54f326b9a', true);
  IF NOT EXISTS (SELECT 1 FROM tenants WHERE id = 'ca7a6e59-866c-40f0-8df1-8ee54f326b9a') THEN
    RAISE EXCEPTION 'Tenant ca7a6e59-866c-40f0-8df1-8ee54f326b9a not found: is this the prod database?';
  END IF;
  VALUES ('ca7a6e59-866c-40f0-8df1-8ee54f326b9a', '2026-11-22T17:51:42.912324+00:00'::timestamptz, '2026-11-22T17:52:20.754857+00:00'::timestamptz, 'finished', 'Imported from local run #14', 'import', 'idcs-c4ccdaeb26104137a0ccf70ec63d6a77', '{"PASS": 2, "FAIL": 10, "MANUAL": 32, "manual_controls": 30, "not_completed": 2, "assessed": 12, "total": 44, "tested": 14}'::jsonb, '')
  RETURNING id INTO rid;



  RAISE NOTICE 'Imported Oracle CIS run % for tenant ca7a6e59-866c-40f0-8df1-8ee54f326b9a', rid;
END
$import$;
COMMIT;
