  (rid, '2.2', 'identity_domain_console_restricted_trusted_networks', 'Ensure OCI Console Access Is Restricted to Trusted Networks', 'L1', '2', 'Networking', 'high', 'automated', 'FAIL', 'FAIL', '[]'::jsonb, '2 console sign-on rule(s) allow access without a network condition (MFA for administrators, MFA for all users). Identity domain side only; tenancy-level IAM network sources are NOT assessed from here. Note: sign-in for some or all users is federated to an external identity provider (Company Single Sign-On Dev, Username-Password). Restrictions configured in that provider are the control point and are not visible from this identity domain.', '2026-11-22T17:52:04+00:00'::timestamptz, '{"wide_open": [], "console_rules": [{"name": "MFA for administrators", "effect": "ALLOW", "policy": "Security Policy for OCI Console", "perimeters": [], "condition_group": "OciConsoleConditionGroups", "mentions_network": false}, {"name": "MFA for all users", "effect": "ALLOW", "policy": "Security Policy for OCI Console", "perimeters": [], "condition_group": "OciConsoleDefaultConditionGroups", "mentions_network": false}], "condition_groups": [{"rule": "MFA for administrators", "conditions": {"operator": "and", "conditions": [{"name": "isInTheseGroups", "operator": "coany", "attributeName": "user.groups[*].value", "attributeValue": "[\"45519b30b18d47698073e43024e9b6b7\"]"}, {"name": "idcsAdminRole", "operator": "co", "attributeName": "user.urn:ietf:params:scim:schemas:oracle:idcs:extension:user:User:appRoles[*].adminRole", "attributeValue": "[\"true\"]"}]}, "condition_group": "OciConsoleConditionGroups"}, {"rule": "MFA for all users", "conditions": {"operator": "and", "conditions": [{"name": "Security Default''s Default Sign-On Condition", "operator": "eq", "attributeName": "target.action", "attributeValue": "\"Login\""}]}, "condition_group": "OciConsoleDefaultConditionGroups"}], "console_policies": ["Security Policy for OCI Console"], "perimeters_defined": []}'::jsonb),
  (rid, '2.3', 'fusion_access_control_list_enabled', 'Ensure Access to Fusion is restricted via Access Control List (ACL)', 'L1', '2', 'Networking', 'medium', 'none', 'MANUAL', 'MANUAL', '["requires_other_access"]'::jsonb, 'Manual control: check it with the audit procedure. Needs: OCI tenancy access (IAM policies, Fusion environment settings, Logging, Monitoring).', '2026-11-22T17:52:04+00:00'::timestamptz, '{"audit_procedure": ["OCI Console > Fusion environment > network settings: ACL enabled with only trusted entries and documented exceptions.", "Test from an unlisted IP to confirm it is blocked."]}'::jsonb),
  (rid, '2.4', 'fusion_location_based_access_enabled', 'Ensure Location-Based Access Control (LBAC) is enabled', 'L1', '2', 'Networking', 'medium', 'none', 'MANUAL', 'MANUAL', '["requires_other_access"]'::jsonb, 'Manual control: check it with the audit procedure. Needs: Fusion Applications Security Console / Audit Reports (IT Security Manager).', '2026-11-22T17:52:04+00:00'::timestamptz, '{"audit_procedure": ["Security Console > Location Based Access: ''Enable Location Based Access'' is selected with valid allowlist entries.", "IT Security Manager role is public to avoid lockout; test from allowed and disallowed IPs."]}'::jsonb),
